const settings = $('Settings').first().json;
const LOCALE = settings.locale;
const CHANNEL = settings.channel;
const STORE_ID_ATTRIBUTE = settings.storeIdAttribute;

const pick = (values, code) => {
  if (!values) return null;
  const common = values.common?.[code];
  if (common !== undefined && common !== null && common !== '') return common;
  const scoped = values.locale_specific?.[LOCALE]?.[code];
  if (scoped !== undefined && scoped !== null && scoped !== '') return scoped;
  return values.channel_locale_specific?.[CHANNEL]?.[LOCALE]?.[code] ?? null;
};

return $input.all().map((item) => {
  const product = item.json;
  const values = product.values ?? {};

  const name = pick(values, 'name');
  const description = pick(values, 'description');
  const price = pick(values, 'price');
  const storeProductId = pick(values, STORE_ID_ATTRIBUTE);
  const active = product.status === true || product.status === 1;

  const missing = [];
  if (!name) missing.push('name');
  if (!description) missing.push('description');
  if (!price) missing.push('price');

  return {
    json: {
      sku: product.sku,
      title: name ?? product.sku,
      description: description ?? '',
      price: price ?? null,
      family: product.family ?? null,
      tags: (product.categories ?? []).join(', '),
      active,
      storeProductId: storeProductId ? String(storeProductId) : null,
      missingFields: missing,
      readyToPublish: missing.length === 0 && active,
      sourceEvent: product.event ?? 'product.updated',
      syncedAt: new Date().toISOString(),
    },
    pairedItem: item.pairedItem,
  };
});
